// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
        // Minimal mock environment so initialize() succeeds (glpManager.vault() must return a code-bearing vault).
        VaultMock vault = new VaultMock();
        GlpManagerMock glpManager = new GlpManagerMock(address(vault));
        // Initialize via low-level call to avoid cross-file interface-type conversion issues.
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.initialize.selector,
                address(1), // sGlp (unused in this scenario)
                address(2), // usdc
                address(3), // rewardRouter
                address(glpManager),
                address(5), // dnGmxJuniorVault
                address(6) // keeper
            )
        );
        require(ok, "initialize failed");
    }

    function testFuzz_property(address newOwner) public {
        // Owner after __Ownable_init is the deployer (this test contract).
        vm.prank(address(this));
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: after a transferOwnership attempt by the owner, owner() is never the zero address:
        // either the call reverted (zero-address transfer rejected), or ownership moved to a non-zero address.
        assertTrue(!ok || c.owner() != address(0));
    }
}

contract VaultMock {
    function getMinPrice(address) external pure returns (uint256) {
        return 1e30;
    }
}

contract GlpManagerMock {
    address public vault;
    constructor(address _vault) {
        vault = _vault;
    }
}
